const genericDeep = (topic: LaterTopic): [string, string][] => [
  ['Передумови й причини', `Процеси теми виникли не раптово: ${topic.intro} Їхні причини пов’язані зі зміною влади, економічними інтересами, соціальними конфліктами та українським прагненням до самоврядування.`],
  ['Перебіг і територія', `Події розгорталися послідовно: ${topic.blocks.map(([, text]) => text).join(' ')}`],
  ['Наслідки й зв’язки', `Головний результат теми — зміна політичного порядку, суспільних відносин і культурного простору. Для НМТ зіставляй наслідки з датами та персоналіями; попередня і наступна теми показують, що цей процес не був ізольованим.`],
]

for (const [id, topic] of Object.entries(laterTopics)) {
  const extra = enrichment[Number(id)]
  topic.deepSections = extra?.deepSections ?? genericDeep(topic)
  topic.map = extra?.map ?? { title: `Карта до теми ${id}`, description: 'Перевіряти території, кордони, міста, напрямки та легенду відповідно до програмних подій цієї теми.', source: 'Оригінальна карта УЦОЯО/ЗНО не підтверджена в локальному наборі; саморобна карта не використовується.', status: 'not-found' }
  topic.landmarks = extra?.landmarks ?? []
  topic.connections = extra?.connections ?? ['Пов’язуй тему з попереднім етапом розвитку українських земель і наступними політичними наслідками.']
}

