for (const id of Object.keys(laterTopics).map(Number).filter((id) => id >= 15 && id <= 32 && id !== 29)) {
  laterTopics[id].programDates = laterTopics[id].dates
}

laterTopics[16].landmarks = [['Резиденція митрополитів Буковини і Далмації', 'Чернівці', '1864–1882', 'історизм, еклектика', 'цегляний ансамбль із трьома корпусами; нині комплекс Чернівецького університету']]
laterTopics[17].landmarks = [['Володимирський собор', 'Київ', '1862–1896', 'неовізантійський стиль', 'хрестово-купольний храм; упізнається за великим центральним куполом і монументальним живописом'], ['Одеський оперний театр', 'Одеса', '1883–1887', 'необароко', 'підкова залу, пишний фасад і скульптурний декор']]
laterTopics[25].landmarks = [['Резиденція митрополитів Буковини і Далмації', 'Чернівці', '1864–1882', 'історизм, еклектика', 'пам’ятка культурного розвитку Буковини; нині комплекс ЧНУ']]

export const laterQuizData: Record<number, { groups: { title: string; askLeft: string; askRight: string; links: [string, string][] }[]; matchingTasks: { pairs: [string, string][] }[] }> = Object.fromEntries(Object.entries(laterTopics).map(([id, topic]) => [Number(id), { groups: [
  { title: 'Дати й події', askLeft: 'Яка подія пов’язана з датою «{value}»?', askRight: 'Коли відбулася подія: «{value}»?', links: topic.dates.map(([date, event]) => [date, event] as [string, string]) },
  { title: 'Персоналії', askLeft: 'Який факт пов’язаний із діячем «{value}»?', askRight: 'Кого описано: «{value}»?', links: topic.people.slice(0, 4).map(([name, detail]) => [name, detail] as [string, string]) },
  { title: 'Поняття', askLeft: 'Яке визначення відповідає поняттю «{value}»?', askRight: 'Про яке поняття йдеться: «{value}»?', links: topic.terms.slice(0, 4).map(([term, definition]) => [term, definition] as [string, string]) },
  { title: 'Причини та наслідки', askLeft: 'Який факт пов’язаний із процесом «{value}»?', askRight: 'Який процес описано: «{value}»?', links: topic.blocks.map(([heading, text]) => [heading, text] as [string, string]) },
], matchingTasks: [] }]))

for (const bank of Object.values(laterQuizData)) bank.matchingTasks = bank.groups.map((group) => ({ pairs: group.links }))
